"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["7056"],{2875(e,i,n){n.r(i),n.d(i,{metadata:()=>t,default:()=>h,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"SoftwareEngineering/architecture-decisions","title":"Architecture Decision Framework","description":"Every page in this course so far has presented trade-offs \u2014 monolith vs microservices, SQL vs NoSQL, strong vs eventual consistency. This page is the repeatable process for actually making these decisions, instead of relying on gut feeling or defaulting to whatever\'s trendy.","source":"@site/docs/SoftwareEngineering/23-architecture-decisions.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/architecture-decisions","permalink":"/Mindstack/docs/SoftwareEngineering/architecture-decisions","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":23,"frontMatter":{"title":"Architecture Decision Framework","sidebar_label":"Architecture Decisions","sidebar_position":23},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Legacy Code","permalink":"/Mindstack/docs/SoftwareEngineering/legacy-code"},"next":{"title":"Anti-Patterns","permalink":"/Mindstack/docs/SoftwareEngineering/anti-patterns"}}'),s=n(4848),a=n(8453);let r={title:"Architecture Decision Framework",sidebar_label:"Architecture Decisions",sidebar_position:23},o="Architecture Decision Framework",l={},c=[{value:"Why a Framework Matters",id:"why-a-framework-matters",level:2},{value:"The Framework",id:"the-framework",level:2},{value:"Step 1 \u2014 Define the Actual Problem",id:"step-1--define-the-actual-problem",level:3},{value:"Step 2 \u2014 Identify Genuinely Viable Options",id:"step-2--identify-genuinely-viable-options",level:3},{value:"Step 3 \u2014 Evaluate Against Explicit Criteria",id:"step-3--evaluate-against-explicit-criteria",level:3},{value:"Step 4 \u2014 Weigh Reversibility Explicitly",id:"step-4--weigh-reversibility-explicitly",level:3},{value:"Step 5 \u2014 Make the Decision and Document It",id:"step-5--make-the-decision-and-document-it",level:3},{value:"Step 6 \u2014 Revisit When Genuinely Warranted",id:"step-6--revisit-when-genuinely-warranted",level:3},{value:"A Worked Mini-Example",id:"a-worked-mini-example",level:2},{value:"Common Decision-Making Pitfalls",id:"common-decision-making-pitfalls",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let i={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(i.header,{children:(0,s.jsx)(i.h1,{id:"architecture-decision-framework",children:"Architecture Decision Framework"})}),"\n",(0,s.jsx)(i.p,{children:"Every page in this course so far has presented trade-offs \u2014 monolith vs microservices, SQL vs NoSQL, strong vs eventual consistency. This page is the repeatable process for actually making these decisions, instead of relying on gut feeling or defaulting to whatever's trendy."}),"\n",(0,s.jsx)(i.hr,{}),"\n",(0,s.jsx)(i.h2,{id:"why-a-framework-matters",children:"Why a Framework Matters"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:'Without a deliberate process, architecture decisions tend to default to:\n\n  Resume-driven development \u2014 choosing a technology because it looks\n  good on a resume or is exciting to learn, not because it fits the\n  problem\n\n  Cargo culting \u2014 "Netflix does microservices, so we should too"\n  without examining whether Netflix\'s actual constraints (massive\n  scale, hundreds of independent teams) apply to your situation at all\n\n  Whoever argues loudest \u2014 the most senior or most persistent voice\n  in the room wins, regardless of whether their reasoning is actually sound\n\nA deliberate framework doesn\'t guarantee the "right" answer \u2014 there\noften isn\'t one single right answer \u2014 but it ensures the decision is\nmade for REASONS that can be examined, questioned, and revisited\nlater, rather than vibes.\n'})}),"\n",(0,s.jsx)(i.hr,{}),"\n",(0,s.jsx)(i.h2,{id:"the-framework",children:"The Framework"}),"\n",(0,s.jsx)(i.h3,{id:"step-1--define-the-actual-problem",children:"Step 1 \u2014 Define the Actual Problem"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:'Before comparing options, write down, specifically:\n  What are we actually trying to solve?\n  What does success look like, concretely?\n  What are the REAL constraints (team size, timeline, budget,\n  existing infrastructure, team\'s existing expertise)?\n\nA surprising amount of architecture debate happens because people are\nimplicitly solving DIFFERENT problems without realizing it \u2014 one\nperson is optimizing for "ship fast this quarter," another is\noptimizing for "this needs to handle 100x our current scale in two\nyears." Neither is wrong, but they\'ll advocate for different\narchitectures until the actual problem and its real constraints are\nmade explicit and shared.\n'})}),"\n",(0,s.jsx)(i.h3,{id:"step-2--identify-genuinely-viable-options",children:"Step 2 \u2014 Identify Genuinely Viable Options"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:'List the real candidates \u2014 not every theoretically possible option,\njust the ones that could plausibly work given the REAL constraints\nfrom Step 1.\n\nIf the team has zero Kubernetes experience and a six-week deadline,\n"build a Kubernetes-orchestrated microservices platform" is not a\ngenuinely viable option for THIS decision, however good an idea it\nmight be in the abstract \u2014 it fails the real constraints already\nestablished.\n'})}),"\n",(0,s.jsx)(i.h3,{id:"step-3--evaluate-against-explicit-criteria",children:"Step 3 \u2014 Evaluate Against Explicit Criteria"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:"Common criteria, weighted by what actually matters for THIS decision\n(not every criterion matters equally every time):\n\n  Complexity                \u2014 how hard to build, understand, and reason about\n  Team familiarity          \u2014 does the team already know this well, or is\n                            there a real learning curve/ramp-up cost\n  Operational cost          \u2014 ongoing maintenance, monitoring, on-call burden\n  Performance               \u2014 does it meet the actual (not imagined)\n                            performance requirement\n  Cost                      \u2014 infrastructure, licensing, engineering time\n  Time to implement         \u2014 does it fit the real timeline\n  Reversibility             \u2014 how expensive is it to change this\n                            decision later if it turns out wrong\n                            (see Step 4)\n  Scalability               \u2014 does it accommodate realistic\n                            future growth, not speculative growth\n                            (echoing YAGNI, file 04)\n\nA simple weighted scoring exercise (even informally, in a document)\nmakes the trade-offs VISIBLE and forces an explicit conversation about\nwhich criteria matter most for this specific decision \u2014 rather than\neach person silently weighting things differently in their head and\ntalking past each other.\n"})}),"\n",(0,s.jsx)(i.h3,{id:"step-4--weigh-reversibility-explicitly",children:"Step 4 \u2014 Weigh Reversibility Explicitly"}),"\n",(0,s.jsx)(i.p,{children:"This is the criterion most decision frameworks skip, and it's often the single most important one."}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:'Amazon\'s "one-way door vs two-way door" framing is genuinely useful here:\n\nTwo-way door decisions:\n  Easy/cheap to reverse if they turn out wrong. Move fast, decide\n  with imperfect information, learn from the outcome, adjust.\n  Example: choosing a specific caching library \u2014 swapping it later,\n  if needed, is a contained, moderate effort.\n\nOne-way door decisions:\n  Expensive or impossible to reverse. Choosing a primary database\n  technology for a system that will hold years of production data;\n  a foundational API contract that many external customers will\n  build against; a core domain model that many other parts of the\n  system will come to depend on.\n  These deserve substantially more upfront analysis, prototyping,\n  and deliberate discussion \u2014 because getting it wrong is expensive\n  to fix later, unlike a two-way door decision.\n\nPractical value: explicitly asking "is this a one-way or two-way\ndoor?" tells you how much decision-making effort is actually\njustified. Spending two weeks deliberating a two-way door decision is\nwasted effort; spending two days on a genuine one-way door decision\nis under-investing in a decision that will be expensive to undo.\n'})}),"\n",(0,s.jsx)(i.h3,{id:"step-5--make-the-decision-and-document-it",children:"Step 5 \u2014 Make the Decision and Document It"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:'Once a decision is made:\n  Record it (an ADR \u2014 see file 21, Documentation) \u2014 what was decided,\n  what alternatives were considered, and WHY this option won, including\n  the specific trade-offs accepted.\n  Make explicit what would cause you to REVISIT this decision \u2014 a\n  specific scale threshold, a specific new requirement, a specific\n  timeline. This turns "we should reconsider this sometime" (vague,\n  never actually happens) into a concrete trigger that prompts a\n  genuine future review.\n'})}),"\n",(0,s.jsx)(i.h3,{id:"step-6--revisit-when-genuinely-warranted",children:"Step 6 \u2014 Revisit When Genuinely Warranted"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:"A good architecture decision made with 2024's information can become\na bad decision by 2026, as constraints change \u2014 this isn't a sign the\noriginal decision was wrong, it's a sign that circumstances evolved\n(this connects directly to file 20's point that prudent, deliberate\ntechnical debt is often reasonable, provided it's revisited when its\nunderlying assumptions change).\n\nThe explicit revisit triggers from Step 5 are what prevent two\nopposite failure modes:\n  Never revisiting a decision, even once the reasons it was made\n  no longer apply (dogmatic attachment to an old decision)\n  Constantly re-litigating settled decisions without a real,\n  new reason to (decision fatigue, wasted debate on already-decided\n  questions)\n"})}),"\n",(0,s.jsx)(i.hr,{}),"\n",(0,s.jsx)(i.h2,{id:"a-worked-mini-example",children:"A Worked Mini-Example"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:'Problem (Step 1): our new feature needs a place to store user\nsession data. Team: 4 engineers. Timeline: ship in 2 weeks. Existing\ninfra: a PostgreSQL database already in production; no existing\nRedis or caching infrastructure.\n\nViable options (Step 2): store sessions in PostgreSQL (existing\ninfra); introduce Redis (new infra, but a more natural technical fit\nfor ephemeral session data \u2014 see file 14, Database Design).\n\nEvaluation (Step 3):\n  PostgreSQL: zero new infrastructure, team already knows it well,\n  slightly less natural fit (a relational database storing\n  ephemeral key-value data), but proven and simple for THIS scale.\n  Redis: better technical fit for the specific access pattern, but\n  new infrastructure to provision, monitor, and operate (see the\n  DevOps course) \u2014 real ongoing operational cost for a 4-person team\n  with a 2-week deadline.\n\nReversibility (Step 4): this is a TWO-WAY DOOR \u2014 session storage is\nan internal implementation detail, not exposed externally; switching\nfrom PostgreSQL to Redis later, if session volume genuinely grows to\njustify it, is a contained, moderate-effort change that doesn\'t\ntouch any external contract.\n\nDecision (Step 5): use PostgreSQL for now \u2014 simpler, fits the real\ntimeline and team size, and the switch to Redis later (if session\nvolume genuinely grows enough to warrant it) is cheap because this\nwas correctly identified as a two-way door. Documented in a short\nADR, with an explicit revisit trigger: "reconsider if session table\nread/write load becomes a measured bottleneck, or exceeds ~X req/sec."\n\nThis is a small example, but the SAME six steps apply, just with more\nanalysis and more stakeholders, for a genuinely large one-way-door\ndecision like choosing a primary database technology or committing\nto a microservices migration (file 09).\n'})}),"\n",(0,s.jsx)(i.hr,{}),"\n",(0,s.jsx)(i.h2,{id:"common-decision-making-pitfalls",children:"Common Decision-Making Pitfalls"}),"\n",(0,s.jsx)(i.pre,{children:(0,s.jsx)(i.code,{children:'Analysis paralysis:\n  Endless research and comparison without ever deciding \u2014 usually a\n  sign the reversibility (Step 4) hasn\'t been assessed; a two-way\n  door decision doesn\'t deserve unlimited analysis time.\n\nSunk cost fallacy:\n  Continuing to defend or build on a past decision because of the\n  effort already invested, rather than re-evaluating based on\n  CURRENT information \u2014 a documented ADR with explicit revisit\n  triggers (Step 5-6) helps counter this by making "should we\n  reconsider?" a scheduled, expected question rather than an\n  uncomfortable confrontation.\n\nFalse dichotomy:\n  Presenting a decision as only two options when a third (often a\n  hybrid, or a smaller first step) genuinely exists \u2014 Step 2 should\n  genuinely search for viable options, not just validate a decision\n  someone already wanted to make.\n\nIgnoring team expertise:\n  Choosing the "objectively best" technology on paper while ignoring\n  that the team has zero experience with it \u2014 this is a real Step 1\n  constraint, not a minor detail; the "best" architecture the team\n  can\'t execute well is often worse in practice than a "good enough"\n  one they can.\n'})}),"\n",(0,s.jsx)(i.hr,{}),"\n",(0,s.jsx)(i.h2,{id:"tips",children:"Tips"}),"\n",(0,s.jsxs)(i.ul,{children:["\n",(0,s.jsx)(i.li,{children:"Make the actual problem and real constraints explicit before comparing options \u2014 a surprising amount of architecture disagreement is really disagreement about the underlying problem, not the proposed solution."}),"\n",(0,s.jsx)(i.li,{children:"Explicitly classify a decision as a one-way or two-way door before deciding how much analysis time it deserves \u2014 this single step prevents both under-analyzing consequential decisions and over-analyzing easily-reversible ones."}),"\n",(0,s.jsx)(i.li,{children:'Document decisions with an ADR, including explicit triggers for when to revisit \u2014 this turns "we should reconsider this sometime" from a vague intention into an actionable, scheduled check.'}),"\n",(0,s.jsx)(i.li,{children:"Treat team familiarity and real timeline constraints as first-class decision criteria, not afterthoughts \u2014 the theoretically best architecture the team can't execute well within real constraints is often the practically worse choice."}),"\n"]}),"\n",(0,s.jsx)(i.hr,{}),"\n",(0,s.jsx)(i.h2,{id:"summary",children:"Summary"}),"\n",(0,s.jsxs)(i.ul,{children:["\n",(0,s.jsx)(i.li,{children:'A deliberate decision framework replaces resume-driven development, cargo-culting, and "whoever argues loudest" with reasoning that can be examined and revisited.'}),"\n",(0,s.jsx)(i.li,{children:"The six steps: define the actual problem and real constraints, identify genuinely viable options, evaluate against explicit weighted criteria, weigh reversibility explicitly (one-way vs two-way door), document the decision (ADR) with revisit triggers, and actually revisit when those triggers occur."}),"\n",(0,s.jsx)(i.li,{children:"Reversibility is the most commonly-skipped, highest-value criterion \u2014 it directly determines how much analysis effort a decision actually deserves."}),"\n",(0,s.jsx)(i.li,{children:'Common pitfalls: analysis paralysis (usually from skipping the reversibility assessment), sunk cost fallacy (mitigated by scheduled revisit triggers), false dichotomies, and ignoring real team expertise/timeline constraints in favor of a theoretically "best" choice.'}),"\n"]})]})}function h(e={}){let{wrapper:i}={...(0,a.R)(),...e.components};return i?(0,s.jsx)(i,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,i,n){n.d(i,{R:()=>r,x:()=>o});var t=n(6540);let s={},a=t.createContext(s);function r(e){let i=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function o(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),t.createElement(a.Provider,{value:i},e.children)}}}]);